// Public OAuth client identifier, never a client secret. Dedicated public PKCE client.
export const MCP_CLIENT_ID = '7a171f80-0e72-481a-a269-e9f16630a1e3';
export const MCP_CALLBACK = 'https://chatgpt.com/connector_platform_oauth_redirect';
// Exact callback generated by the existing private ChatGPT connection. No wildcard.
export const MCP_CALLBACKS: readonly string[] = [
  MCP_CALLBACK,
  'https://chatgpt.com/connector/oauth/mrt8uuQriKVd',
];
export function authorizationId(search: string): string | null {
  const values = new URLSearchParams(search).getAll('authorization_id');
  return values.length === 1 && /^[a-zA-Z0-9_-]{1,128}$/.test(values[0]) ? values[0] : null;
}
export function safeMcpRedirect(value: string): string | null {
  try {
    const url = new URL(value);
    return MCP_CALLBACKS.includes(url.origin + url.pathname) && !url.username && !url.password && !url.hash ? url.href : null;
  } catch { return null; }
}
export function allowedMcpRequest(details: { client: { id: string }; redirect_uri: string; scope: string }): boolean {
  return details.client.id === MCP_CLIENT_ID && MCP_CALLBACKS.includes(details.redirect_uri) &&
    details.scope.split(' ').filter(Boolean).every(scope => ['openid', 'email', 'offline_access'].includes(scope));
}
